package de.lazytv.pro.playlist;
import android.content.Context;import android.net.Uri;import java.io.InputStream;
public final class PlaylistValidator {private PlaylistValidator(){}public static String validate(Playlist playlist){if(playlist==null)return"Playlist nuk është valide";if(blank(playlist.getName()))return"Shkruaj emrin e playlistës";if(playlist.getType()==null)return"Zgjidh llojin e playlistës";if(blank(playlist.getUrl()))return playlist.getType()==PlaylistType.M3U_FILE?"Zgjidh skedarin M3U":"Shkruaj URL-në";if(playlist.getType()==PlaylistType.M3U_FILE){if(!isContentUri(playlist.getUrl()))return"Skedari M3U nuk është valid";}else if(!isHttp(playlist.getUrl()))return"URL duhet të fillojë me http:// ose https://";if(playlist.getType()==PlaylistType.XTREAM_CODES){if(blank(playlist.getUsername()))return"Shkruaj username";if(blank(playlist.getPassword()))return"Shkruaj password";}if(playlist.getType()==PlaylistType.STALKER_PORTAL){if(blank(playlist.getMacAddress()))return"Shkruaj MAC / Device identifier";if(!isMacAddress(playlist.getMacAddress()))return"MAC duhet të jetë në formatin 00:1A:79:XX:XX:XX";}return null;}public static String validateForConnect(Context context,Playlist playlist){String error=validate(playlist);if(error!=null)return error;if(playlist.getType()!=PlaylistType.M3U_FILE)return null;try(InputStream stream=context.getContentResolver().openInputStream(Uri.parse(playlist.getUrl()))){if(stream==null)return"Skedari M3U nuk mund të hapet";return null;}catch(Exception e){return"Nuk ka më qasje te skedari M3U. Edito playlistën dhe zgjidhe skedarin përsëri.";}}private static boolean blank(String value){return value==null||value.trim().isEmpty();}private static boolean isHttp(String value){try{String scheme=Uri.parse(value.trim()).getScheme();return"http".equalsIgnoreCase(scheme)||"https".equalsIgnoreCase(scheme);}catch(Exception e){return false;}}private static boolean isContentUri(String value){try{return"content".equalsIgnoreCase(Uri.parse(value.trim()).getScheme());}catch(Exception e){return false;}}private static boolean isMacAddress(String value){return value!=null&&value.trim().matches("(?i)^[0-9A-F]{2}(:[0-9A-F]{2}){5}$");}}
